package studio.jiayu.neoagent;
import android.content.*;import org.json.*;
/** Real MainActivity/Bridge callback guards with a debug-only send interceptor, no provider replacement. */
final class VoiceUiContracts {
 static int checks;static void yes(boolean value,String why)throws Exception{if(!value)throw new Exception(why);checks++;}
 static long arm(UiQaActivity a){long lease=a.voice.session.begin(true);a.voice.session.listening(lease);a.voiceOwnerSession=a.sessionId;return lease;}
 static void unchanged(UiQaActivity a,int submissions,long turn,String why)throws Exception{yes(a.voiceGuardSubmissions==submissions&&a.turn==turn&&!a.planning,why);}
 static void run(UiQaActivity a){JSONObject report=VoiceChatContracts.source();OfflineVoice previous=a.voice;boolean direct=false,hadDirect=false,prefsCaptured=false,replaced=false;checks=0;try{
  ControlService service=ControlService.instance;yes(service!=null&&service.connected&&!service.busy()&&!a.planning,"Runtime not idle");yes(a.resumed&&a.loaded&&a.voiceUiTest(),"Isolated chat UI not ready");yes(previous==null||!previous.active(),"Existing recording active");
  SharedPreferences prefs=a.getSharedPreferences("ui",0);hadDirect=prefs.contains("voiceDirect");direct=prefs.getBoolean("voiceDirect",false);prefsCaptured=true;a.voice=new OfflineVoice(a,new OfflineVoice.Listener(){public boolean foreground(){return a.resumed;}public void state(JSONObject value){}public void result(String text,boolean auto){a.voiceResult(text,auto);}public void error(String message){}});replaced=true;
  a.newChat();String first=a.sessionId;long initialTurn=a.turn;
  arm(a);int initial=a.voiceGuardSubmissions;a.voiceResult("打开微信",true);yes(a.voiceGuardSubmissions==initial+1&&a.turn==initialTurn,"Positive callback did not reach debug send interceptor");a.cancelVoice();
  int sent=a.voiceGuardSubmissions;long turn=a.turn;
  long old=arm(a);a.new Bridge().action("voiceCancel","{}");yes(!a.voice.active()&&a.voiceOwnerSession.isEmpty(),"Cancel did not revoke recording");yes(a.voice.session.finish(old,true)==null,"Cancelled recognition still finalizes");a.voiceResult("取消后的旧回调",true);unchanged(a,sent,turn,"Cancelled final reached chat submission");
  old=arm(a);a.newChat();yes(!first.equals(a.sessionId),"New chat did not switch session");yes(a.voice.session.finish(old,true)==null,"New chat retained old recognition");a.voiceResult("新建聊天后的旧回调",true);unchanged(a,sent,turn,"Old final entered new chat");
  old=arm(a);a.new Bridge().action("openChat",new JSONObject().put("id",first).toString());yes(a.sessionId.equals(first)&&!a.voice.active(),"Switch chat did not cancel recording");yes(a.voice.session.finish(old,true)==null,"Switch chat retained old recognition");a.voiceResult("切换聊天后的旧回调",true);unchanged(a,sent,turn,"Switched-session final entered chat");
  old=arm(a);a.new Bridge().action("voiceMode",new JSONObject().put("direct",!direct).toString());yes(!a.voice.active()&&a.voiceOwnerSession.isEmpty(),"Mode change retained recording");yes(a.voice.session.finish(old,true)==null,"Mode change retained old recognition");a.voiceResult("旧模式中的回调",true);unchanged(a,sent,turn,"Old-mode final submitted after mode change");
  old=arm(a);int beforeManual=a.voiceGuardSubmissions;a.new Bridge().action("send",new JSONObject().put("text","手动输入测试").toString());yes(a.voiceGuardSubmissions==beforeManual+1&&!a.voice.active(),"Manual send did not cancel recording");yes(a.voice.session.finish(old,true)==null,"Manual send retained old recognition");a.voiceResult("手动输入后的旧回调",true);unchanged(a,beforeManual+1,turn,"Old final followed manual send");
  Intent original=a.getIntent();boolean consumed=a.taskConsumed;int intercepted=a.voiceGuardSubmissions;a.onNewIntent(new Intent(a,UiQaActivity.class).putExtra("task","voice_daily").putExtra("send",true));yes(a.getIntent()==original&&a.voiceUiTest()&&a.taskConsumed==consumed,"SingleTop switched guard mode into live planner");yes(a.voiceGuardSubmissions==intercepted,"Rejected mode switch submitted a task");a.onNewIntent(new Intent(a,UiQaActivity.class).putExtra("task","adaptive_daily").putExtra("send",true));yes(a.getIntent()==original&&a.taskConsumed==consumed,"SingleTop left isolation or reset consumed task");
  report.put("success",true).put("checks",checks).put("real_network_calls",0).put("third_party_actions",0).put("microphone_permission_requested",false).put("fake_provider_installed",false).put("send_interception","debug UI guard test only; positive real-planner path is separate voice_daily task").put("cancel_rejected",true).put("new_chat_rejected",true).put("switch_chat_rejected",true).put("mode_change_rejected",true).put("manual_send_rejected",true).put("fixture_mode_switch_rejected",true).put("duplicate_send_state_preserved",true).put("real_microphone_acceptance",false);
 }catch(Exception failed){try{report.put("success",false).put("checks",checks).put("failure",failed.getMessage()).put("failure_type",failed.getClass().getSimpleName());}catch(Exception ignored){}}
 finally{if(replaced){a.cancelVoice();if(a.voice!=null&&a.voice!=previous)a.voice.close();a.voice=previous;}if(prefsCaptured){SharedPreferences.Editor editor=a.getSharedPreferences("ui",0).edit();if(hadDirect)editor.putBoolean("voiceDirect",direct);else editor.remove("voiceDirect");editor.commit();}if(replaced)try{new Vault(a).remove("test-voice-user-memory");new Vault(a).remove("test-voice-chats");}catch(Exception ignored){}VoiceChatContracts.write(a,"voice-ui-contracts.json",report);a.finish();}}
}
